import re, sys, os, subprocess

# Scan for functions containing a head-realloc call; within the function, find
# identifier uses that look like pointers into skb data captured BEFORE the call
# and used AFTER the call.
COW_CALLS = re.compile(r'\b(skb_cow_head|skb_cow|skb_unclone|skb_share_check|pskb_expand_head|skb_linearize|pskb_may_pull|pskb_pull|__pskb_pull_tail)\s*\(')

# patterns of capture: identifier = something involving skb->data / skb_header_pointer / *_hdr(skb) casts
CAPTURE = re.compile(
    r'(?P<lhs>[A-Za-z_][A-Za-z0-9_]*)\s*(?::\s*[A-Za-z_][A-Za-z0-9_:]*)?\s*=\s*'
    r'(?P<rhs>(?:[^;\n]|sizeof\([^)]*\))*?);'
)

PTR_HINT = re.compile(
    r'skb_header_pointer\s*\(|skb->data|skb->head|skb_tail_pointer|skb_network_header|skb_mac_header|'
    r'skb_transport_header|skb_pull_data|skb->cb|skb_shinfo|\(struct\s+\w+\s*\*\)\s*skb->|'
    r'vlan_eth_hdr|eth_hdr\s*\(|ip_hdr\s*\(|ipv6_hdr\s*\(|tcp_hdr\s*\(|udp_hdr\s*\(|'
    r'sctp_hdr|dccp_hdr|icmp_hdr|igmp_hdr|arp_hdr|nsh_hdr|mpls_hdr|gre_hdr|esp_hdr|ah_hdr|'
    r'ipoib_hdr|ipip_hdr|geneve_hdr|vxlan_hdr|gue_hdr|frag_hdr|tcphdr|iphdr'
)

def read_lines(path):
    with open(path, 'r', errors='replace') as f:
        return f.readlines()

def functions(lines):
    """Yield (start, end, name) of top-level-ish functions by brace matching."""
    i = 0
    n = len(lines)
    while i < n:
        line = lines[i]
        m = re.match(r'^[A-Za-z_].*\)\s*$', line) or re.match(r'^[A-Za-z_].*\)\s*\{?\s*$', line)
        # find function signature heuristically: line(s) before a line ending '{' at col 0
        if line.startswith('{') :
            # find preceding signature
            j = i - 1
            sig_start = j
            while j >= 0 and not re.match(r'^[A-Za-z_].*\)\s*$', lines[j]) and not lines[j].rstrip().endswith(')'):
                j -= 1
                if i - j > 12: break
            if j >= 0:
                name_m = re.search(r'([A-Za-z_][A-Za-z0-9_]*)\s*\(', lines[j])
                if name_m and lines[j].lstrip().startswith(('static','int','void','bool','struct','u','unsigned','__be','sk_buff','char','const','inline','netdev_tx_t','int ','bool ')) or (name_m and re.match(r'^[A-Za-z_]', lines[j])):
                    pass
            yield None
        i += 1

def split_functions(text):
    """Split C text into functions using simple brace matching from line starts."""
    funcs = []
    lines = text.split('\n')
    idx = 0
    n = len(lines)
    while idx < n:
        line = lines[idx]
        # candidate function start: signature line that ends with ')' possibly '{'
        if re.match(r'^[A-Za-z_][A-Za-z0-9_ \t\*:]*$', line) or re.search(r'\)\s*$', line):
            # look ahead for the opening brace within 5 lines
            k = idx
            brace_line = None
            while k < idx + 6 and k < n:
                if '{' in lines[k]:
                    brace_line = k
                    break
                if re.match(r'^\}', lines[k]) or re.match(r'^[A-Za-z_]', lines[k]) and k > idx:
                    break
                k += 1
            if brace_line is not None:
                # extract name
                nm = None
                for l in lines[idx:brace_line+1]:
                    m = re.search(r'([A-Za-z_][A-Za-z0-9_]*)\s*\(', l)
                    if m and m.group(1) not in ('if','for','while','switch','sizeof','return'):
                        nm = m.group(1)
                        break
                if nm:
                    # brace match
                    depth = 0
                    j = brace_line
                    while j < n:
                        depth += lines[j].count('{') - lines[j].count('}')
                        if depth <= 0:
                            break
                        j += 1
                    if j < n and depth <= 0:
                        funcs.append((idx, j, nm))
                        idx = j + 1
                        continue
        idx += 1
    return funcs

def strip_comments_strings(text):
    # remove comments
    text = re.sub(r'/\*.*?\*/', '/* */', text, flags=re.S)
    text = re.sub(r'//[^\n]*', '//', text)
    return text

def analyze(path):
    with open(path, 'r', errors='replace') as f:
        raw = f.read()
    text = strip_comments_strings(raw)
    lines = text.split('\n')
    out = []
    for (fs, fe, name) in split_functions(text):
        body_lines = lines[fs:fe+1]
        body = '\n'.join(body_lines)
        cow_matches = [ (i, body_lines[i]) for i in range(len(body_lines)) if COW_CALLS.search(body_lines[i]) ]
        if not cow_matches:
            continue
        # find capture statements: assignments where RHS references pointer-ish things
        candidates = {}
        for i, bline in enumerate(body_lines):
            for m in re.finditer(r'([A-Za-z_][A-Za-z0-9_]*)\s*(?::[A-Za-z0-9_:]+)?\s*=\s*([^;]+);', bline):
                lhs, rhs = m.group(1), m.group(2)
                if lhs in ('i','j','k','n','len','len1','err','ret','rc','res'):
                    continue
                if re.search(r'\b(int|u8|u16|u32|u64|s8|s16|s32|s64|__u8|__u16|__u32|__u64|__be16|__be32|__le16|__le32|bool|unsigned|size_t|__wsum|__sum16|netdev_tx_t|atomic_t|void|char)\b', rhs.split('=')[0] if '=' in rhs else rhs):
                    # still could be pointer cast; only skip if no cast to pointer
                    if not re.search(r'\*\s*\)', rhs):
                        continue
                if PTR_HINT.search(rhs):
                    candidates.setdefault(lhs, i)
        for (ci, cowline) in cow_matches:
            func_name = name
            # for each candidate captured before cow line index, find uses after
            for var, cap_line in candidates.items():
                if cap_line >= ci:
                    continue
                # uses after
                uses = []
                for i in range(ci, len(body_lines)):
                    if i == ci and var == 'skb':
                        continue
                    for um in re.finditer(r'(?<![A-Za-z0-9_])' + re.escape(var) + r'\b\s*(?:->|\[|\.|\+|\)|;)', body_lines[i]):
                        uses.append(i)
                        break
                if uses:
                    out.append((path, fs+ci+1, func_name, var, fs+cap_line+1, [fs+u+1 for u in uses], body_lines[ci].strip()))
    return out

if __name__ == '__main__':
    base = sys.argv[1]
    results = []
    for root, dirs, files in os.walk(base):
        for fn in files:
            if fn.endswith('.c'):
                p = os.path.join(root, fn)
                try:
                    results.extend(analyze(p))
                except Exception as e:
                    print(f"ERR {p}: {e}", file=sys.stderr)
    for r in results:
        print('\t'.join([r[0], str(r[1]), r[2], r[3], str(r[4]), ','.join(map(str,r[5])), r[6]]))
